/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var proxyquire = require( 'proxyquire' );
var discreteUniform = require( '@stdlib/random/base/discrete-uniform' );
var Float64Array = require( '@stdlib/array/float64' );
var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major' );
var dgemm = require( '@stdlib/blas/base/dgemm' ).ndarray;
var floor = require( '@stdlib/math/base/special/floor' );
var depth = require( './../lib/depth.js' );
var storeMatrix = require( './fixtures/store_matrix.js' );
var firstDifference = require( './fixtures/first_difference.js' );


// VARIABLES //

var SEED = 20261104;
var TRANS = [ 'no-transpose', 'transpose' ];
var ORDERS = [ 'row-major', 'column-major' ];
var DIM = 37; // M = N = K
var CUTOFF = 3;

// Code paths of the conventional multiplications performed by the recursion (recorded by a spy):
var paths = [];

var winograd = proxyquire( './../lib/winograd.js', {
	'@stdlib/blas/base/dgemm': {
		'ndarray': leaf
	}
});

var base = proxyquire( './../lib/base.js', {
	'./winograd.js': winograd
});


// FUNCTIONS //

/**
* Tests whether a provided string indicates to transpose a matrix.
*
* @private
* @param {string} str - input string
* @returns {boolean} boolean indicating whether to transpose a matrix
*/
function isTransposed( str ) {
	return ( str !== 'no-transpose' );
}

/**
* Returns the code path taken by `dgemm` for a given set of arguments.
*
* ## Notes
*
* -   This function mirrors the dispatch logic of `@stdlib/blas/base/dgemm/lib/base.js` exactly: quick return, scaling only (when `α = 0`), the "naive" (cache-optimal) algorithm, or the "blocked" (loop tiling) algorithm.
*
* @private
* @param {string} transA - transpose operation for `A`
* @param {string} transB - transpose operation for `B`
* @param {NonNegativeInteger} M - number of rows
* @param {NonNegativeInteger} N - number of columns
* @param {NonNegativeInteger} K - inner dimension
* @param {number} alpha - scalar constant
* @param {NumericArray} sa - strides of `A`
* @param {NumericArray} sb - strides of `B`
* @param {number} beta - scalar constant
* @returns {string} code path
*/
function dgemmPath( transA, transB, M, N, K, alpha, sa, sb, beta ) {
	var isrma;
	var isrmb;

	if ( M === 0 || N === 0 || ( ( beta === 1.0 ) && ( ( alpha === 0.0 ) || ( K === 0 ) ) ) ) {
		return 'quick-return';
	}
	if ( alpha === 0.0 ) {
		return 'scale';
	}
	isrma = isRowMajor( sa );
	isrmb = isRowMajor( sb );
	if ( isrma ) {
		if ( !isTransposed( transA ) ) {
			if ( !isrmb && !isTransposed( transB ) ) {
				return 'naive';
			}
			if ( isrmb && isTransposed( transB ) ) {
				return 'naive';
			}
		}
	} else if ( isTransposed( transA ) ) {
		if ( isrmb && isTransposed( transB ) ) {
			return 'naive';
		}
		if ( !isrmb && !isTransposed( transB ) ) {
			return 'naive';
		}
	}
	return 'blocked';
}

/**
* Records the code path of a conventional multiplication and invokes `dgemm`.
*
* @private
* @param {string} transA - transpose operation for `A`
* @param {string} transB - transpose operation for `B`
* @param {NonNegativeInteger} M - number of rows
* @param {NonNegativeInteger} N - number of columns
* @param {NonNegativeInteger} K - inner dimension
* @param {number} alpha - scalar constant
* @param {Float64Array} A - first matrix
* @param {integer} strideA1 - stride of the first dimension of `A`
* @param {integer} strideA2 - stride of the second dimension of `A`
* @param {NonNegativeInteger} offsetA - starting index for `A`
* @param {Float64Array} B - second matrix
* @param {integer} strideB1 - stride of the first dimension of `B`
* @param {integer} strideB2 - stride of the second dimension of `B`
* @param {NonNegativeInteger} offsetB - starting index for `B`
* @param {number} beta - scalar constant
* @param {Float64Array} C - third matrix
* @param {integer} strideC1 - stride of the first dimension of `C`
* @param {integer} strideC2 - stride of the second dimension of `C`
* @param {NonNegativeInteger} offsetC - starting index for `C`
* @returns {Float64Array} `C`
*/
function leaf( transA, transB, M, N, K, alpha, A, strideA1, strideA2, offsetA, B, strideB1, strideB2, offsetB, beta, C, strideC1, strideC2, offsetC ) { // eslint-disable-line max-params
	paths.push( dgemmPath( transA, transB, M, N, K, alpha, [ strideA1, strideA2 ], [ strideB1, strideB2 ], beta ) );
	return dgemm( transA, transB, M, N, K, alpha, A, strideA1, strideA2, offsetA, B, strideB1, strideB2, offsetB, beta, C, strideC1, strideC2, offsetC );
}

/**
* Returns a dense matrix of random integers in `[-6,6]`.
*
* @private
* @param {Function} randi - PRNG for integers
* @param {NonNegativeInteger} len - number of elements
* @returns {Float64Array} matrix
*/
function random( randi, len ) {
	var out;
	var i;

	out = new Float64Array( len );
	for ( i = 0; i < len; i++ ) {
		out[ i ] = randi( -6, 6 );
	}
	return out;
}

/**
* Runs all combinations of layouts of `A`, `B`, and `C` and transpose operations, and verifies that every conventional multiplication performed by the recursion takes the same `dgemm` code path as the top-level call with the original arguments would.
*
* @private
* @param {Object} t - test object
* @param {number} beta - scalar constant
*/
function verify( t, beta ) {
	var expected;
	var counts;
	var randi;
	var opts;
	var bad;
	var ref;
	var out;
	var ta;
	var tb;
	var A;
	var B;
	var C;
	var i;
	var j;

	randi = discreteUniform.factory({
		'seed': SEED
	});
	counts = {
		'naive': 0,
		'blocked': 0
	};
	for ( i = 0; i < 64; i++ ) {
		ta = TRANS[ i%2 ];
		tb = TRANS[ floor( i/2 )%2 ];
		opts = [];
		for ( j = 0; j < 3; j++ ) {
			// Bits 2-4 select the layouts of `A`, `B`, and `C`; bit 5 selects padding, offsets, and negative strides...
			opts.push({
				'order': ORDERS[ floor( i/pow2( j+2 ) )%2 ],
				'pad': ( i >= 32 ) ? 2 : 0,
				'offset': ( i >= 32 ) ? 3 : 0,
				'tail': ( i >= 32 ) ? 1 : 0,
				'flip1': ( i >= 32 && j !== 1 ),
				'flip2': ( i >= 32 && j !== 0 )
			});
		}
		A = storeMatrix( random( randi, DIM*DIM ), DIM, DIM, ta, opts[ 0 ], NaN );
		B = storeMatrix( random( randi, DIM*DIM ), DIM, DIM, tb, opts[ 1 ], NaN );
		C = storeMatrix( random( randi, DIM*DIM ), DIM, DIM, 'no-transpose', opts[ 2 ], NaN );

		expected = dgemmPath( ta, tb, DIM, DIM, DIM, 2.0, [ A.s1, A.s2 ], [ B.s1, B.s2 ], beta );
		counts[ expected ] += 1;

		ref = new Float64Array( C.buf );
		out = new Float64Array( C.buf );
		dgemm( ta, tb, DIM, DIM, DIM, 2.0, A.buf, A.s1, A.s2, A.o, B.buf, B.s1, B.s2, B.o, beta, ref, C.s1, C.s2, C.o );
		paths = [];
		base( ta, tb, DIM, DIM, DIM, 2.0, A.buf, A.s1, A.s2, A.o, B.buf, B.s1, B.s2, B.o, beta, out, C.s1, C.s2, C.o, CUTOFF, 100 );

		bad = 0;
		for ( j = 0; j < paths.length; j++ ) {
			if ( paths[ j ] !== expected ) {
				bad += 1;
			}
		}
		t.ok( paths.length > 0 && bad === 0, 'all ' + paths.length + ' conventional multiplications take the "' + expected + '" path (' + [ ta, tb, opts[ 0 ].order, opts[ 1 ].order, opts[ 2 ].order ].join( ', ' ) + ( ( i >= 32 ) ? ', padding, offsets, negative strides' : '' ) + '; ' + bad + ' mismatches)' );
		t.strictEqual( firstDifference( ref, out, beta === 0.0 ), -1, 'returns expected value' );
	}
	t.strictEqual( counts.naive, 16, 'the top-level call takes the "naive" path in 16 of 64 combinations' );
	t.strictEqual( counts.blocked, 48, 'the top-level call takes the "blocked" path in 48 of 64 combinations' );
}

/**
* Returns `2^n`.
*
* @private
* @param {NonNegativeInteger} n - exponent
* @returns {PositiveInteger} power of two
*/
function pow2( n ) {
	var out = 1;
	var i;
	for ( i = 0; i < n; i++ ) {
		out *= 2;
	}
	return out;
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof base, 'function', 'main export is a function' );
	t.end();
});

tape( 'the problem size recurses', function test( t ) {
	t.strictEqual( depth( DIM, DIM, DIM, CUTOFF, 100 ), 4, 'returns expected value' );
	t.end();
});

tape( 'every conventional multiplication performed by the recursion takes the same `dgemm` code path as the top-level call (β = 0; product formed in C)', function test( t ) {
	verify( t, 0.0 );
	t.end();
});

tape( 'every conventional multiplication performed by the recursion takes the same `dgemm` code path as the top-level call (β ≠ 0; product formed in a temporary having the layout of C)', function test( t ) {
	verify( t, 2.0 );
	t.end();
});
